-- DevFoundry: command-based repository scaffolding.
-- Run once in the Supabase SQL editor after 004_assign_existing_conversations.sql.
--
-- The repository structure is generated by real CLI commands (e.g. `npx --yes create-vite@latest frontend --template react-ts`).
-- scaffold_commands  : the commands that produced the generator output, in order ([{"command": "...", "cwd": "."}]).
-- scaffold_structure : the generator output exactly as produced ([{"path", "content", "encoding"?}]).
-- The reviewed `structure` = scaffold_structure + the changes the user asked for. The first push commits the generator
-- output on its own, then the requested changes as a second commit.
-- Without these columns the app still works, but the structure is pushed as one commit.

alter table public."Repository"
    add column if not exists scaffold_commands  jsonb,
    add column if not exists scaffold_structure jsonb;

-- Make PostgREST pick up the new columns immediately.
notify pgrst, 'reload schema';
